// test_env_var.rs - Minimal test case for std::env::var parsing
// Generated by step4_bootstrap - Debug env::var

use split_decls_genesis::{extract_all_symbols_from_file_fast};

fn main() {
    println!("🔍 Testing std::env::var parsing specifically...");
    
    let env_file = "../rust/library/std/src/env.rs";
    println!("📄 Parsing: {}", env_file);
    
    match extract_all_symbols_from_file_fast(env_file, "std") {
        Ok(symbols) => {
            println!("✅ Extracted {} symbols from env.rs", symbols.len());
            
            // Look for var function specifically
            let var_symbols: Vec<_> = symbols.iter()
                .filter(|s| s.name.contains("var"))
                .collect();
            
            println!("\n🔍 All var-related symbols:");
            for symbol in &var_symbols {
                println!("  - {}: {} (deps: {})", 
                    symbol.name, 
                    symbol.symbol_type,
                    symbol.dependencies.len()
                );
            }
            
            // Check if we have the exact var function
            if let Some(var_fn) = symbols.iter().find(|s| s.name == "var") {
                println!("\n✅ Found var function:");
                println!("  Type: {}", var_fn.symbol_type);
                println!("  Dependencies: {:?}", var_fn.dependencies);
            } else {
                println!("\n❌ var function NOT found");
                
                // Show all function symbols to debug
                let functions: Vec<_> = symbols.iter()
                    .filter(|s| s.symbol_type.starts_with("fn"))
                    .collect();
                
                println!("\n📋 All functions found ({}):", functions.len());
                for (i, func) in functions.iter().take(20).enumerate() {
                    println!("  {}. {}: {}", i+1, func.name, func.symbol_type);
                }
                
                if functions.len() > 20 {
                    println!("  ... and {} more", functions.len() - 20);
                }
            }
            
            // Check raw file content for var function
            if let Ok(content) = std::fs::read_to_string(env_file) {
                let var_lines: Vec<_> = content.lines()
                    .enumerate()
                    .filter(|(_, line)| line.contains("pub fn var"))
                    .collect();
                
                println!("\n📝 Raw file search for 'pub fn var':");
                for (line_num, line) in var_lines {
                    println!("  Line {}: {}", line_num + 1, line.trim());
                }
            }
        },
        Err(e) => {
            println!("❌ Failed to parse env.rs: {}", e);
        }
    }
}
